#pragma once
#include "PublicationCommit.hpp"
#include "PublicationCatalogProof.hpp"
namespace udm {
// One identity covers both catalog records and both final file locations.
class ReplacementCommit {
public:
 static std::string identity(const Json& op){if(!op.contains("CommitId"))return {};auto id=PublicationCommit::identity(op);if(str(op.at("OriginalAfter"),"PublicationCommitId")!=id||str(op.at("Before"),"Id")!=str(op,"Id")||str(op.at("After"),"Id")!=str(op,"Id")||str(op.at("OriginalBefore"),"Id")!=str(op,"OriginalId")||str(op.at("OriginalAfter"),"Id")!=str(op,"OriginalId")||str(op,"Id")==str(op,"OriginalId"))throw std::runtime_error("Replacement completion identity changed. Keep both files and the recovery journal.");PublicationCatalogProof::binding(op.at("After"));PublicationCatalogProof::binding(op.at("OriginalAfter"));auto path=[](const Json& row){return(fs::path(wide(str(row,"Folder")))/wide(str(row,"FileName"))).lexically_normal();};const auto target=fs::path(wide(str(op,"Target"))).lexically_normal(),previous=fs::path(wide(str(op,"Previous"))).lexically_normal(),stage=fs::path(wide(str(op,"Staging"))).lexically_normal();if(!target.is_absolute()||!previous.is_absolute()||!stage.is_absolute()||windowsPath::equal(windowsPath::key(target),windowsPath::key(previous))||windowsPath::equal(windowsPath::key(target),windowsPath::key(stage))||windowsPath::equal(windowsPath::key(previous),windowsPath::key(stage))||path(op.at("Before"))!=target||path(op.at("OriginalBefore"))!=target||path(op.at("After"))!=target||path(op.at("OriginalAfter"))!=previous||!std::regex_match(str(op,"OldHash"),std::regex("[a-f0-9]{64}"))||!std::regex_match(str(op,"NewHash"),std::regex("[a-f0-9]{64}"))||str(op.at("After"),"Sha256")!=str(op,"NewHash")||str(op.at("OriginalAfter"),"Sha256")!=str(op,"OldHash"))throw std::runtime_error("Replacement paths or hashes changed. Keep both files and the recovery journal.");return id;}
 static void validateCurrent(const Json& op,const Json& current,const Json& original){auto id=identity(op);if(id.empty())return;for(const auto& pair:{std::pair<const Json*,const Json*>{&current,&op.at("Before")},{&original,&op.at("OriginalBefore")}}){auto stamp=str(*pair.first,"PublicationCommitId");if(stamp!=id&&stamp!=str(*pair.second,"PublicationCommitId"))throw std::runtime_error("A newer publication owns a replacement record. Keep both files and the recovery journal.");}}
 static Json applyOriginal(const Json& before,const Json& after,const Json& current){auto result=current;for(auto it=before.begin();it!=before.end();++it)if(!after.contains(it.key()))result.erase(it.key());for(auto it=after.begin();it!=after.end();++it)if(!before.contains(it.key())||before.at(it.key())!=it.value())result[it.key()]=it.value();for(const char* key:{"Id","Folder","FileName","Status","Size","Received","Sha256","Finished","PublicationCommitId","PreviousVersionOf","QueueMember","SyncPending"})if(after.contains(key))result[key]=after.at(key);return result;}
 static bool rowAccepted(const Json& expected,const Json& current){for(const char* key:{"Id","Folder","FileName","Status","Size","Received","Sha256","Finished","PublicationCommitId"})if(!current.contains(key)||!expected.contains(key)||current.at(key)!=expected.at(key))return false;return true;}
 static bool accepted(const Json& op,const Json& current,const Json& original){return !identity(op).empty()&&rowAccepted(op.at("After"),current)&&rowAccepted(op.at("OriginalAfter"),original);}
};
}
